    hint: '日本の本州の多くが属します。',
    explanation:
      '【何を聞かれているか】一年が暖かい季節と寒い季節（四季）に分かれ日本の多くの地域が属する気候帯である。\n\n【なぜそうなるのか】赤道から離れて太陽の光が斜めに当たるようになると気温が下がるが、極に近すぎない中緯度では暑すぎず寒すぎない気候になる。\n\n【ステップ1】温帯は夏と冬の気温差があり四季の変化がはっきりし、雨も適度に降るので作物が育ちやすく世界の人口の多くがこの気候帯に住んでいる。気候帯は緯度の順に並ぶ（熱帯→乾燥帯→温帯→冷帯→寒帯）。\n\n【ステップ2】温帯は3つに区分され、温暖湿潤気候（夏は高温多湿、冬は冷える、季節風の影響、日本の本州・四国・九州）、西岸海洋性気候（夏は涼しく冬も比較的あたたか、一年を通して雨、ヨーロッパ西部、暖流の北大西洋海流と偏西風の影響）、地中海性気候（夏は暑く乾燥し冬に雨、地中海沿岸、オリーブ・ぶどう・オレンジの栽培）。日本は大部分が温帯で北海道だけが冷帯、南西諸島は亜熱帯と呼ばれる。\n\n【答え】温帯\n\n【確かめ】雨温図で夏に雨が多ければ温暖湿潤、冬に多ければ地中海性と見分けられる点を確認する。\n\n【よくあるまちがい】日本全体が温帯だと思ってしまう。北海道は冷帯（亜寒帯）、南西諸島は亜熱帯であり、大部分が温帯というのが正しい。\n\n【ここが絶対】「温帯の3区分（温暖湿潤・西岸海洋性・地中海性）」は地理の最頻出事項。',
    examFrequency: 'high',
