      '【何を聞かれているか】710年に唐の長安にならってつくられ奈良時代の都となった都である。\n\n【なぜそうなるのか】当時の日本は唐の制度を取り入れて国のしくみを整えている最中で、都のつくりもその一部として唐の都をまねた。\n\n【ステップ1】平城京は710年にいまの奈良市につくられ、ここから794年までを奈良時代という。東西南北にまっすぐな道路を通して碁盤の目のように区切られ（条坊制）、北の中央に天皇の住まいと役所（平城宮）を置きそこから南へ朱雀大路がのびる。\n\n【ステップ2】聖武天皇が国ごとに国分寺・国分尼寺を建て東大寺に大仏をつくらせ、墾田永年私財法（743年）で新しく開いた土地の永久の私有を認めたことで貴族や寺社が私有地（荘園）を広げ公地公民の原則がくずれていった。『古事記』『日本書紀』『万葉集』『風土記』がつくられ、正倉院にはシルクロードを通って伝わった宝物が納められている。\n\n【答え】平城京\n\n【確かめ】「なんと（710）きれいな平城京」の語呂で年代を確認する。\n\n【よくあるまちがい】平城京と平安京を混同する。平城京は奈良（710年）、平安京は京都（794年）である。\n\n【ここが絶対】「平城京（710年、奈良、条坊制）」は歴史の最頻出事項。',
