      '【答え】福沢諭吉\n\n【『学問のすゝめ』】1872年から1876年にかけて17編に分けて出され、当時としては異例の売れ行きだった。\n\n【有名な書き出しの読み方】「天は人の上に人を造らず人の下に人を造らず」。ここだけを読むと平等を説いた本に見えるが、文章はこう続く。現実には賢い人と愚かな人、豊かな人と貧しい人の差がある。そのちがいはどこから来るのか。学んだか学ばなかったかの差である、と。つまり平等を説いた本ではなく、学ぶことをすすめた本である。ここを読みまちがえないこと。\n\n【なぜ当時ひびいたのか】身分制度がなくなったばかりの時代に、生まれではなく努力で道が開けると説いたからである。新しい世の中の生き方を示す本として受け入れられた。\n\n【福沢諭吉のほかの仕事】『西洋事情』で欧米の様子を紹介し、慶應義塾を開いて多くの人材を育てた。長くお札の肖像にも使われた。\n\n【同じ時代の思想家】中江兆民はフランスのルソーの思想を翻訳して紹介し、自由民権運動に影響を与えた。福沢は学問、中江は民権思想と分けて覚える。\n\n【背景】明治の文明開化のなかで、欧米の考え方が次々に紹介された時期である。',
