      '【答え】国民主権・基本的人権の尊重・平和主義\n\n【なぜこの3つなのか】3つはばらばらではなく、同じ反省から出ている。大日本帝国憲法では主権が天皇にあり、国民の権利は法律の範囲内でしか認められず、戦争を止める仕組みもなかった。その結果が、多くの命を失った戦争である。だから主権を国民に移し、権利を法律でも奪えないものにし、二度と戦争をしないと定めた。3つでひとそろいの答えになっている。\n\n【①国民主権】国の政治を最終的に決める力は国民にある（前文・第1条）。天皇は政治の権限を持たず、日本国と国民統合の象徴とされる。\n\n【②基本的人権の尊重】人が生まれながらに持つ権利で、侵すことのできない永久の権利とされる（第11条）。自由権・平等権・社会権・参政権・請求権に分けられる。\n\n【③平和主義】第9条に、戦争の放棄・戦力の不保持・交戦権の否認が定められている。ここまではっきり書いた憲法は世界でもめずらしい。\n\n【条文とセットで】国民主権は前文と第1条、基本的人権は第11条、平和主義は第9条。原則と条文を組にして問われることが多い。\n\n【日付】1946年11月3日公布（文化の日）、1947年5月3日施行（憲法記念日）。',
