      '【答え】インフレーション（インフレ）\n\n【どういうことか】物価が上がり続けると、同じ1000円で買えるものが減る。つまりお金の価値が下がるということである。物の値段が上がることと、お金の価値が下がることは、同じことを裏表から言っている。\n\n【なぜ起きるのか】\n・景気がよく、みんながたくさん買おうとする（需要が増える）\n・原油や原材料の値段が上がり、作る費用が上がる\n・お金が世の中に出回りすぎる\n\n【だれが困るのか】年金や貯金で暮らす人である。もらう額は変わらないのに、買えるものが減っていくからである。いっぽう、お金を借りている人は返す負担が実質的に軽くなる。\n\n【反対の現象】デフレーション（デフレ）は、物価が下がり続けてお金の価値が上がること。一見よさそうだが、物が売れず → 企業の利益が減り → 給料が下がり → ますます買わなくなる、という悪い循環（デフレスパイラル）に陥ることがある。\n\n【調整するのはだれか】\n・日本銀行 … 金融政策。インフレのときは金利を上げてお金を借りにくくし、出回る量を減らす\n・政府 … 財政政策。公共事業や増減税で調整する\n\n【日本銀行の3つの役割】発券銀行・政府の銀行・銀行の銀行。',
