    hint: '内閣総理大臣は国会議員から選ばれます。',
    explanation:
      '【答え】議院内閣制\n\n【どんな仕組みか】\n・内閣総理大臣は、国会議員の中から国会の議決で指名される\n・国務大臣の過半数は国会議員でなければならない\n・内閣は国会に対して連帯して責任を負う（第66条）\n・衆議院が内閣不信任を決議すれば、内閣は10日以内に総辞職するか衆議院を解散する\nこの4つがそろって、内閣が国会の信任のうえに立つ形になる。\n\n【なぜこうするのか】国民が選ぶのは国会議員である。その国会が内閣をつくり、内閣を監視する。こうして国民 → 国会 → 内閣と責任の線がつながり、国民の意思が行政に届く。\n\n【大統領制とのちがい】アメリカの大統領制では、国民が大統領を直接選ぶ。大統領は議会の信任を必要とせず、議会を解散することもできない。議会の議員が大臣を兼ねることもない。議院内閣制は立法と行政の結びつきが強く、大統領制は分離が強い。\n\n【「連帯して」の意味】ある大臣の失敗を、その大臣ひとりの問題にせず、内閣全体で責任を負うということ。だから閣議は全会一致が慣例である。\n\n【よくあるまちがい】国民が首相を選ぶのではない。国民が選ぶのは国会議員である。',
