      '【答え】地方自治\n\n【なぜ「民主主義の学校」と呼ばれるのか】イギリスのブライスの言葉とされる。国の政治は遠くて実感しにくいが、地方の政治はごみの収集・学校・道路・公園など、毎日の暮らしに直接関わる。身近だからこそ関心を持ちやすく、参加の経験を積むことができる。地方で民主主義を身につけ、それが国全体を支えるという考え方である。\n\n【国とちがう仕組み】\n・首長（知事・市町村長）も議員も、住民が直接選挙で選ぶ（二元代表制）。国では首相を国民が直接選ばない\n・住民が直接請求できる\n\n【直接請求権】\n・条例の制定・改廃、監査の請求 … 有権者の50分の1以上\n・議会の解散、首長・議員の解職（リコール）… 有権者の3分の1以上。その後の住民投票で過半数の同意が必要\n提案は50分の1、地位を奪うのは3分の1と、意味の重さで分かれている。\n\n【財源の課題】地方公共団体の収入のうち、自分で集める地方税（自主財源）は半分に満たないところが多く、国からの地方交付税交付金や国庫支出金にたよっている。財源と権限を地方に移す地方分権が進められている。',
