    answer: '象徴',
    hint: '政治の権力はもちません。',
    explanation:
      '【答え】象徴\n\n【条文】第1条「天皇は、日本国の象徴であり日本国民統合の象徴であつて、この地位は、主権の存する日本国民の総意に基く」。\n\n【「象徴」とはどういうことか】天皇は国の政治についての権限を一切持たない。国会の議決や内閣の決定に関わることはなく、国民をまとめる存在としての役割にとどまる。しかも、その地位は国民の総意にもとづくと定められている。国民が主権者だからこそ、天皇の地位も国民の意思の上にあるという組み立てになっている。\n\n【国事行為】天皇が行う形式的・儀礼的な行為で、すべて内閣の助言と承認が必要であり、その責任は内閣が負う。\n・内閣総理大臣の任命（国会が指名した人を）\n・最高裁判所長官の任命（内閣が指名した人を）\n・憲法改正・法律・条約の公布\n・国会の召集、衆議院の解散\n・栄典の授与、外国の大使の接受\n「指名」と「任命」を必ず分ける。決めるのは国会や内閣で、天皇は形式的に任命するだけである。\n\n【大日本帝国憲法とのちがい】かつて天皇は主権者であり、統治権と軍の指揮権（統帥権）を持っていた。',
