      '【答え】熊本県（静岡県も上位）\n\n【みかんの主な産地】和歌山県・愛媛県・静岡県・熊本県が上位を占め、年によって順位が入れかわる。いずれも冬でも比較的あたたかい太平洋側や瀬戸内海ぞいにある。\n\n【なぜこの県なのか】みかんは寒さに弱く、冬に強い冷えこみがあると木がいたむ。さらに、次の3つがそろう土地でよく育つ。\n①南向きの斜面 … 日がよく当たる\n②水はけのよい土 … みかんは水が多すぎると味がうすくなる。斜面なら雨水がすぐ流れる\n③海の近く … 海面で反射した光が下からも当たり、実全体が色づく。海は気温の急な変化もやわらげる\n平らな土地よりあえて斜面を選んでいるところが、この作物の産地の特徴である。\n\n【熊本県のほかの産物】トマト・すいかの生産も全国上位で、い草（畳表の原料）はほぼ全国の生産を占める。阿蘇山には世界有数の大きさのカルデラがある。\n\n【果物と気候の対応】\n・すずしい … りんご（青森）、さくらんぼ（山形）\n・昼夜の差が大きい盆地 … ぶどう・もも（山梨）\n・あたたかい … みかん（和歌山・愛媛・静岡・熊本）',
    examFrequency: 'medium',
