    answer: '産業の空洞化',
    hint: '工場が外国へ出ていくことで起こります。',
    explanation:
      '【答え】産業の空洞化\n\n【どういうことか】日本の企業が工場を海外へ移した結果、国内の工場が減り、そこで働いていた人の仕事がなくなり、その地域の技術も受けつがれなくなる現象をいう。中身が抜けて外側だけ残ることから「空洞化」という。\n\n【なぜ工場が海外へ出たのか】\n①円高 … 1985年のプラザ合意の後、急速に円高が進んだ。円高になると、日本でつくって輸出する製品は外国から見て高くなり売れにくい。そこで、売る国でつくるほうが有利になった\n②人件費のちがい … 中国や東南アジアは賃金が安く、同じものを安くつくれる\n③貿易摩擦を避けるため … 日本の自動車が大量に輸出されてアメリカの産業を圧迫し、対立が起きた。現地に工場を建てて現地の人を雇えば、その批判をやわらげられる\n\n【何が問題か】働く場所が減ること、そして長年つちかった技術が国内から失われることである。とくに大企業の下請けをしていた中小工場への影響が大きい。\n\n【どう向き合うか】ほかの国にまねできない高い技術の製品や、研究開発の力で勝負する方向が探られている。安さで競うのをやめ、質で競うという考え方である。',
